// Mark order paid (Guest Session integration callback)
router.post("/orders/:id/mark-paid", async (req, res) => {
  const { sessionToken } = req.body;
  const { data: session } = await supabaseAdmin
    .from('dining_sessions')
    .select('id')
    .eq('token', sessionToken)
    .single();
  
  if (!session) return res.status(401).json({ error: "Invalid session token" });

  const { data: existingOrder } = await supabaseAdmin
    .from('orders')
    .select('id,restaurant_id,table_id,session_id,order_type,status,total_price,payment_method,payment_id,paid_at,idempotency_key,session_token,items,created_at,updated_at')
    .eq('id', req.params.id)
    .eq('session_id', session.id)
    .single();

  if (!existingOrder) return res.status(404).json({ error: "Order not found" });

  if (existingOrder.paid_at) {
    return res.json(existingOrder);
  }

  // Only allow direct confirmation for CASH payments
  if (existingOrder.payment_method === 'cash') {
    const { data, error } = await supabaseAdmin
      .from('orders')
      .update({ 
        paid_at: new Date().toISOString(), 
        status: 'confirmed', 
        payment_method: 'cash' 
      })
      .eq('id', req.params.id)
      .eq('session_id', session.id)
      .select()
      .single();
    
    if (error) return res.status(500).json({ error: error.message });
    return res.json(data);
  }

  // Reject direct mark-paid requests for digital/online orders
  return res.status(400).json({ error: "Online orders can only be marked PAID via verified Stripe signature webhook." });
});

